definition.script:
import groovy.json.JsonSlurper;

def retrieveBuildSpecId = ''
def build_hashes = [:]
def infrastructure_git_hash
def targetStack
def pipelineBuildId

pipeline {
  agent any

  environment {
    SOURCE_SCRIPTS_FOLDER = "${JENKINS_HOME}/workspace/Bash_Functions/"
  }

  stages {
    stage('Retrieve Build Spec') {
      steps {
        script {
          def result = build job: 'Retrieve Build Spec', parameters: [
            [$class: 'StringParameterValue', name: 'RELEASE_CONTROL_BRANCH', value: RELEASE_CONTROL_BRANCH]
          ]
          retrieveBuildSpecId = result.number
        }
        script {
          copyArtifacts filter: '*', projectName: 'Retrieve Build Spec', selector: specific("" + retrieveBuildSpecId)
          sh 'cat build-spec.json'
          sh 'cat pipeline_git_commit.txt'
          def buildSpec = new JsonSlurper().parseText(readFile('build-spec.json'))
          pipelineBuildId = readFile('pipeline_git_commit.txt').trim()
          for (def build : buildSpec.application) {
            build_hashes[build.project_job_git_key] = build.git_hash
          }
          infrastructure_git_hash = buildSpec.infrastructure_git_hash
        }
      }
    }

    stage('Retrieve Stack') {
        steps {
            script {
                targetStack = sh(script: """
                bash -c '
                set +x

                if [ ! -d "$SOURCE_SCRIPTS_FOLDER" ]; then
                    echo "Error: Source folder does not exist: $SOURCE_SCRIPTS_FOLDER"
                    exit 1
                fi

                for script_file in "$SOURCE_SCRIPTS_FOLDER"*.sh; do
                    chmod +x "\$script_file"
                    if [ -f "\$script_file" ] && [ -x "\$script_file" ]; then
                        . "\$script_file"  # Use dot (.) instead of `source`
                    fi
                done

                # The PIC-SURE Pipeline is always used to deploy to staging.
                get_stack \"${TARGET_STACK}\"
                '
                """, returnStdout: true).trim()

                println "TARGET_STACK: $targetStack"
            }
        }
    }

    stage('Database Migrations (once)') {
      when {
        expression { return params.RUN_DATABASE_MIGRATIONS && (params.INCLUDE_PIC_SURE_API || params.INCLUDE_PIC_SURE_AUTH_MICRO_APP || params.INCLUDE_PIC_SURE_VISUALIZATION) }
      }
      steps {
        script {
          lock('shared-db') {
            echo "Running migrations with infrastructure_git_hash=${infrastructure_git_hash}"
            build job: 'Database Migrations', parameters: [
              [$class: 'StringParameterValue', name: 'infrastructure_git_hash', value: infrastructure_git_hash]
            ]
          }
        }
      }
    }


    stage('Monorepo Build and Package') {
      steps {
        script {
          lock("stack-${targetStack}") {
            def needsMonorepo = params.INCLUDE_PIC_SURE_API || params.INCLUDE_PIC_SURE_HPDS_AUTH || params.INCLUDE_PIC_SURE_HPDS_OPEN || params.INCLUDE_PIC_SURE_AUTH_MICRO_APP || params.INCLUDE_PIC_SURE_VISUALIZATION || params.INCLUDE_PIC_SURE_DICTIONARY || params.INCLUDE_PIC_SURE_LOGGING
            if (needsMonorepo) {
              build job: 'PIC-SURE Maven Build', parameters: [
                [$class: 'StringParameterValue', name: 'git_hash', value: build_hashes['PSA']],
                [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]
              ]
            }
            def imageParams = [
              [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
              [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]
            ]
            def branches = [:]
            if (params.INCLUDE_PIC_SURE_API) {
              branches['gateway']    = { build job: 'PIC-SURE Gateway Image', parameters: imageParams }
              branches['operations'] = { build job: 'PIC-SURE Operations Service Image', parameters: imageParams }
              branches['query']      = { build job: 'PIC-SURE HPDS Query Service Image', parameters: imageParams }
            }
            if (params.INCLUDE_PIC_SURE_HPDS_AUTH || params.INCLUDE_PIC_SURE_HPDS_OPEN) { branches['hpds'] = { build job: 'PIC-SURE HPDS Build', parameters: imageParams } }
            if (params.INCLUDE_PIC_SURE_AUTH_MICRO_APP) { branches['psama'] = { build job: 'PIC-SURE Auth Micro App Build', parameters: imageParams } }
            if (params.INCLUDE_PIC_SURE_VISUALIZATION)  { branches['visualization'] = { build job: 'PIC-SURE Visualization Build', parameters: imageParams } }
            if (params.INCLUDE_PIC_SURE_DICTIONARY)     { branches['dictionary'] = { build job: 'PIC-SURE Dictionary Build', parameters: imageParams } }
            if (params.INCLUDE_PIC_SURE_LOGGING)        { branches['logging'] = { build job: 'PIC-SURE Logging Build', parameters: imageParams } }
            if (branches) { parallel branches }

            if (params.INCLUDE_PIC_SURE_VISUALIZATION) {
              build job: 'Render PIC-SURE Visualization Config Template', parameters: [
                [$class: 'StringParameterValue', name: 'INFRASTRUCTURE_GIT_HASH', value: infrastructure_git_hash],
                [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack]
              ]
            }

            parallel (
              wildfly_stack_deploy: {
                def shouldDeploy = params.INCLUDE_PIC_SURE_API || params.INCLUDE_PIC_SURE_AUTH_MICRO_APP || params.INCLUDE_PIC_SURE_DICTIONARY || params.INCLUDE_PIC_SURE_VISUALIZATION
                if (shouldDeploy) {
                  build job: 'PIC-SURE Wildfly Stack Deploy', parameters: [
                    [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                    [$class: 'StringParameterValue', name: 'DATASET_S3_OBJECT_KEY', value: String.valueOf(params.DATASET_S3_OBJECT_KEY)],
                    [$class: 'BooleanParameterValue', name: 'DEPLOY_GATEWAY', value: params.INCLUDE_PIC_SURE_API],
                    [$class: 'BooleanParameterValue', name: 'DEPLOY_OPERATIONS', value: params.INCLUDE_PIC_SURE_API],
                    [$class: 'BooleanParameterValue', name: 'DEPLOY_QUERY', value: params.INCLUDE_PIC_SURE_API],
                    [$class: 'BooleanParameterValue', name: 'DEPLOY_PSAMA', value: params.INCLUDE_PIC_SURE_AUTH_MICRO_APP],
                    [$class: 'BooleanParameterValue', name: 'DEPLOY_DICTIONARY', value: params.INCLUDE_PIC_SURE_DICTIONARY],
                    [$class: 'BooleanParameterValue', name: 'DEPLOY_VISUALIZATION', value: params.INCLUDE_PIC_SURE_VISUALIZATION]
                  ]
                } else {
                  echo 'Skipping Wildfly Stack Deploy (no wildfly-host components selected)'
                }
              },
              frontend_deploy: {
                if (params.INCLUDE_PIC_SURE_FRONTEND) {
                  build job: 'PIC-SURE Frontend Deploy', parameters: [
                    [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack]
                  ]
                } else {
                  echo 'Skipping PIC-SURE Frontend Deploy'
                }
              },
              hpds_auth_deploy: {
                if (params.INCLUDE_PIC_SURE_HPDS_AUTH) {
                  build job: 'PIC-SURE HPDS Auth Deploy', parameters: [
                    [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                    [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: String.valueOf(params.STACK_S3_BUCKET)],
                    [$class: 'StringParameterValue', name: 'DATA_S3_OBJECT_KEY', value: String.valueOf(params.DATA_S3_OBJECT_KEY)],
                    [$class: 'StringParameterValue', name: 'GENOMIC_DATASET_S3_OBJECT_KEY', value: String.valueOf(params.GENOMIC_DATASET_S3_OBJECT_KEY)]
                  ]
                } else {
                  echo 'Skipping HPDS Auth Deploy'
                }
              },
              hpds_open_deploy: {
                if (params.INCLUDE_PIC_SURE_HPDS_OPEN) {
                  build job: 'PIC-SURE HPDS Open Deploy', parameters: [
                    [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                    [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: String.valueOf(params.STACK_S3_BUCKET)],
                    [$class: 'StringParameterValue', name: 'DESTIGMATIZED_DATASET_S3_OBJECT_KEY', value: String.valueOf(params.DESTIGMATIZED_DATASET_S3_OBJECT_KEY)]
                  ]
                } else {
                  echo 'Skipping HPDS Open Deploy'
                }
              },
              logging_deploy: {
                if (params.INCLUDE_PIC_SURE_LOGGING) {
                  build job: 'PIC-SURE Logging Deploy', parameters: [
                    [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack]
                  ]
                } else {
                  echo 'Skipping PIC-SURE Logging Deploy'
                }
              }
            )
          }
        }
      }
    }

  }
}
